 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separators are full rows/columns; identify their color from full solid lines.
    sep = next((grid[r][0] for r in range(h) if all(x == grid[r][0] for x in grid[r])), None)
    if sep is None:
        sep = next((grid[0][c] for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))), None)
    if sep is None:
        return [row[:] for row in grid]
    row_starts = [r for r in range(h) if grid[r][0] != sep]
    col_starts = [c for c in range(w) if grid[0][c] != sep]
    # Panel origins are non-separator runs; use contiguous run starts.
    def runs(indices):
        out=[]
        for x in indices:
            if not out or x != out[-1][-1]+1: out.append([x])
            else: out[-1].append(x)
        return [a[0] for a in out]
    rs, cs = runs(row_starts), runs(col_starts)
    bg = grid[rs[0]][cs[0]]
    # Select the non-marker object in an interior panel as the pattern.
    shape = None
    marker_color = {}
    for ri, r0 in enumerate(rs):
        vals=[grid[r0+1][c] for c in range(cs[0], min(cs[0]+4,w)) if grid[r0+1][c] not in (bg,sep)]
        if vals: marker_color[ri]=vals[0]
    for r0 in rs:
        for c0 in cs[1:]:
            cells=[(r-r0,c-c0) for r in range(r0,min(r0+4,h)) for c in range(c0,min(c0+4,w)) if grid[r][c] not in (bg,sep)]
            if cells:
                shape=cells
                break
        if shape: break
    if not shape: return [row[:] for row in grid]
    out=[row[:] for row in grid]
    for ri,r0 in enumerate(rs):
        color=marker_color.get(ri)
        if color is None: continue
        for c0 in cs:
            for dr,dc in shape:
                r,c=r0+dr,c0+dc
                if r<h and c<w and grid[r][c]!=sep: out[r][c]=color
    return out
